from urllib.parse import urlsplit, parse_qs

PORTAS_PADRAO = {"http": 80, "https": 443}


def partes_da_url(url):
    partes = urlsplit(url)
    consulta = {}
    for chave, valores in parse_qs(partes.query).items():
        consulta[chave] = valores[0] if len(valores) == 1 else valores
    return {
        "esquema": partes.scheme,
        "host": partes.hostname,
        "porta": partes.port or PORTAS_PADRAO[partes.scheme],
        "caminho": partes.path or "/",
        "consulta": consulta,
    }


