        return resposta_json({"erro": f"JSON inválido (linha {e.lineno}, coluna {e.colno})"}, 400)
    if not isinstance(dados, dict):
        return resposta_json({"erro": "O corpo deve ser um objeto JSON"}, 400)
    nome = dados.get("nome", "visitante")
    return resposta_json({"mensagem": f"Olá, {nome}!"}, 200)


