from miniweb import App, abortar

app = App()

TIMES = []


@app.depois
def marcar_versao(req, resp):
    resp.cabecalhos["X-API-Versao"] = "1"
    return resp


def e_lista_de_textos(valor):
    return isinstance(valor, list) and all(isinstance(item, str) for item in valor)


def nome_em_uso(nome):
    return any(inscrito["nome"].lower() == nome.lower() for inscrito in TIMES)


@app.post("/times")
def inscrever_time(req):
    dados = req.json
    if not isinstance(dados, dict):
        abortar(400, "Envie um objeto JSON")
    nome = dados.get("nome")
    membros = dados.get("membros")
    if not isinstance(nome, str) or not nome.strip() or not e_lista_de_textos(membros):
        abortar(400, "Envie nome (texto) e membros (lista de textos)")
    if not 2 <= len(membros) <= 4:
        abortar(422, "Um time precisa ter de 2 a 4 membros")
    nome = nome.strip()
    if nome_em_uso(nome):
        abortar(409, "Já existe um time com esse nome")
    novo = {
        "id": max((inscrito["id"] for inscrito in TIMES), default=0) + 1,
        "nome": nome,
        "membros": list(membros),
    }
    TIMES.append(novo)
    return novo, 201


@app.get("/times/<int:id>")
def ver_time(req, id):
    for inscrito in TIMES:
        if inscrito["id"] == id:
            return inscrito
    abortar(404, "Time não encontrado")


if __name__ == "__main__":
    cliente = app.cliente()
    pedidos = [
        {"nome": "Dragões", "membros": ["Ana", "Bia", "Caio"]},
        {"nome": "dragões", "membros": ["Duda", "Léo"]},
        {"nome": "Lobos", "membros": ["Rafa"]},
        {"nome": "Lobos", "membros": "Rafa e João"},
    ]
    for corpo in pedidos:
        resp = cliente.post("/times", json=corpo)
        print(resp.status, resp.json(), resp.cabecalhos.get("X-API-Versao"))
    resp = cliente.get("/times/1")
    print(resp.status, resp.json(), resp.cabecalhos.get("X-API-Versao"))

