import itertools

from miniweb import App, abortar

app = App()

ITENS = {
    1: {"id": 1, "nome": "Poção de vida", "preco": 15.0},
    2: {"id": 2, "nome": "Espada curta", "preco": 120.0},
}
IDS = itertools.count(3)


def buscar_item(id):
    if id not in ITENS:
        abortar(404, "Item não encontrado")
    return ITENS[id]


def e_preco_valido(valor):
    return isinstance(valor, (int, float)) and not isinstance(valor, bool) and valor >= 0


def validar(dados, parcial=False):
    # Devolve a mensagem de erro, ou None se estiver tudo certo.
    # Com parcial=True (PATCH), só confere os campos que vieram.
    if not isinstance(dados, dict):
        return "Envie um objeto JSON"
    if "nome" in dados or not parcial:
        nome = dados.get("nome")
        if not isinstance(nome, str) or not nome.strip():
            return "nome deve ser um texto não vazio"
    if "preco" in dados or not parcial:
        if not e_preco_valido(dados.get("preco")):
            return "preco deve ser um número maior ou igual a zero"
    return None


def exigir_valido(dados, parcial=False):
    erro = validar(dados, parcial)
    if erro is not None:
        abortar(400, erro)


def campos_editaveis(dados):
    campos = {}
    if "nome" in dados:
        campos["nome"] = dados["nome"].strip()
    if "preco" in dados:
        campos["preco"] = dados["preco"]
    return campos


@app.get("/itens")
def listar_itens(req):
    return list(ITENS.values())


@app.get("/itens/<int:id>")
def ver_item(req, id):
    return buscar_item(id)


@app.post("/itens")
def criar_item(req):
    exigir_valido(req.json)
    item = {"id": next(IDS)}
    item.update(campos_editaveis(req.json))
    ITENS[item["id"]] = item
    return item, 201


@app.put("/itens/<int:id>")
def substituir_item(req, id):
    buscar_item(id)
    exigir_valido(req.json)
    item = {"id": id}
    item.update(campos_editaveis(req.json))
    ITENS[id] = item
    return item


@app.patch("/itens/<int:id>")
def alterar_item(req, id):
    item = buscar_item(id)
    exigir_valido(req.json, parcial=True)
    item.update(campos_editaveis(req.json))
    return item


@app.delete("/itens/<int:id>")
def apagar_item(req, id):
    buscar_item(id)
    del ITENS[id]
    return "", 204


if __name__ == "__main__":
    cliente = app.cliente()
    resp = cliente.post("/itens", json={"nome": "Escudo", "preco": 80})
