import itertools

from miniweb import App, abortar

app = App()

PONTUACOES = []
IDS = itertools.count(1)
LIMITE_PADRAO = 3
LIMITE_MAXIMO = 100
ERRO_LIMITE = "limite deve ser um inteiro entre 1 e 100"


def e_inteiro(valor):
    return isinstance(valor, int) and not isinstance(valor, bool)


def validar_pontuacao(dados):
    # Devolve (jogador, pontos) já limpos, ou aborta com o erro certo.
    if not isinstance(dados, dict):
        abortar(400, "Envie um objeto JSON")
    jogador = dados.get("jogador")
    if not isinstance(jogador, str) or not jogador.strip():
        abortar(400, "jogador deve ser um texto não vazio")
    pontos = dados.get("pontos")
    if not e_inteiro(pontos):
        abortar(400, "pontos deve ser um número inteiro")
    if pontos < 0:
        abortar(422, "pontos não pode ser negativo")
    return jogador.strip(), pontos


def ler_limite(req):
    try:
        limite = int(req.consulta.get("limite", LIMITE_PADRAO))
    except ValueError:
        abortar(400, ERRO_LIMITE)
    if not 1 <= limite <= LIMITE_MAXIMO:
        abortar(400, ERRO_LIMITE)
    return limite


def melhores_por_jogador():
    melhores = {}
    for pontuacao in PONTUACOES:
        jogador, pontos = pontuacao["jogador"], pontuacao["pontos"]
        melhores[jogador] = max(pontos, melhores.get(jogador, pontos))
    return melhores


@app.post("/pontuacoes")
def registrar_pontuacao(req):
    jogador, pontos = validar_pontuacao(req.json)
    pontuacao = {"id": next(IDS), "jogador": jogador, "pontos": pontos}
    PONTUACOES.append(pontuacao)
    return pontuacao, 201


@app.get("/ranking")
def ranking(req):
    limite = ler_limite(req)
    ordem = sorted(melhores_por_jogador().items(), key=lambda par: (-par[1], par[0]))
    return [
        {"posicao": posicao, "jogador": jogador, "pontos": pontos}
        for posicao, (jogador, pontos) in enumerate(ordem[:limite], start=1)
    ]


@app.get("/jogadores/<nome>/melhor")
def melhor_do_jogador(req, nome):
    pontos = [p["pontos"] for p in PONTUACOES if p["jogador"] == nome]
    if not pontos:
        abortar(404, "Jogador não encontrado")
    return {"jogador": nome, "melhor": max(pontos), "partidas": len(pontos)}


